items.solution:
function costOfNthChange(n, baseCost, couplingPenaltyPercent) {
  const growth = couplingPenaltyPercent / 100;
  const cost = baseCost * Math.pow(1 + growth, n - 1);
  return Math.round(cost * 100) / 100;
}
